// byID 是规范标识到定义下标的索引，避免每次查找线性扫描。
var byID = func() map[string]int {
	m := make(map[string]int, len(defs))
	for i, d := range defs {
		m[d.ID] = i
	}
	return m
}()

// All 返回全部属性定义的副本，调用方可安全修改返回值。
func All() []Def {
	out := make([]Def, len(defs))
	copy(out, defs)
	return out
}

// Lookup 按规范标识查找属性定义。
func Lookup(id string) (Def, bool) {
	i, ok := byID[id]
	if !ok {
		return Def{}, false
	}
	return defs[i], true
}

// MustLookup 与 Lookup 相同，但未命中时 panic —— 仅用于「属性名在编译期即确定」的
// 内部调用点；任何来自配置或网络的属性名都必须走 Lookup 并处理缺失分支。
func MustLookup(id string) Def {
	d, ok := Lookup(id)
	if !ok {
		panic("未登记的属性标识: " + id)
	}
	return d
}

// IDs 按真源顺序返回全部属性标识。
func IDs() []string {
	out := make([]string, 0, len(defs))
	for _, d := range defs {
		out = append(out, d.ID)
	}
	return out
}

// Count 返回已登记属性数量。
func Count() int { return len(defs) }

// RegistryVersion 是真源版本号，供运行期上报与控制台提示。
const RegistryVersion = 1
